<script setup lang="ts">
import { computed, ref, watch } from 'vue';
type Row = Record<string, unknown>;
type Column = { key: string; label: string };
const props = defineProps<{ rows: Row[]; columns: Column[]; storageKey: string; canAdd?: boolean }>();
const emit = defineEmits<{ add: [] }>();
const query = ref(''); const sortKey = ref(''); const descending = ref(false); const settingsOpen = ref(false);
const visible = ref<string[]>(props.columns.map(c => c.key));
const order = ref<string[]>(props.columns.map(c => c.key));
const key = computed(() => `wayalong.table.${props.storageKey}`);
try { const saved = JSON.parse(localStorage.getItem(key.value) || '{}'); if (Array.isArray(saved.visible)) visible.value = saved.visible; if (Array.isArray(saved.order)) order.value = saved.order; } catch { /* defaults */ }
watch([visible, order], () => { try { localStorage.setItem(key.value, JSON.stringify({ visible: visible.value, order: order.value })); } catch { /* optional */ } }, { deep: true });
const shown = computed(() => order.value.map(k => props.columns.find(c => c.key === k)).filter((c): c is Column => !!c && visible.value.includes(c.key)));
const filtered = computed(() => props.rows.filter(row => Object.values(row).some(v => String(v ?? '').toLowerCase().includes(query.value.toLowerCase()))).sort((a,b) => { const result = String(a[sortKey.value] ?? '').localeCompare(String(b[sortKey.value] ?? ''), undefined, { numeric: true }); return descending.value ? -result : result; }));
const sort = (key: string) => { descending.value = sortKey.value === key && !descending.value; sortKey.value = key; };
const move = (key: string, offset: number) => { const i = order.value.indexOf(key); const j = i + offset; if (j < 0 || j >= order.value.length) return; const next = [...order.value]; [next[i], next[j]] = [next[j], next[i]]; order.value = next; };
const exportCsv = () => { const escape = (value: unknown) => `"${String(value ?? '').replace(/"/g, '""')}"`; const csv = [shown.value.map(c => escape(c.label)).join(','), ...filtered.value.map(row => shown.value.map(c => escape(row[c.key])).join(','))].join('\r\n'); const link = document.createElement('a'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); link.href = url; link.download = `${props.storageKey}.csv`; link.click(); URL.revokeObjectURL(url); };
</script>
<template><div class="space-y-4"><div class="flex flex-wrap items-center gap-2"><input v-model="query" type="search" aria-label="Search rows" placeholder="Search all columns…" class="min-w-40 flex-1 rounded-md border bg-background px-3 py-2 text-sm" /><button class="rounded-md border px-3 py-2 text-sm" @click="settingsOpen = !settingsOpen">Column settings</button><button class="rounded-md border px-3 py-2 text-sm" @click="exportCsv">Export CSV</button><button v-if="canAdd" class="rounded-md bg-primary px-3 py-2 text-sm text-primary-foreground" @click="emit('add')">+ Add</button></div><div v-if="settingsOpen" class="rounded-lg border bg-card p-4"><h3 class="mb-3 font-medium">Visible columns and order</h3><div v-for="column in order.map(k => columns.find(c => c.key === k)).filter((c): c is Column => !!c)" :key="column.key" class="flex items-center gap-3 py-1 text-sm"><label class="flex flex-1 items-center gap-2"><input v-model="visible" type="checkbox" :value="column.key" />{{ column.label }}</label><button aria-label="Move column up" class="rounded border px-2" @click="move(column.key,-1)">↑</button><button aria-label="Move column down" class="rounded border px-2" @click="move(column.key,1)">↓</button></div></div><div class="overflow-x-auto rounded-lg border"><table class="w-full text-left text-sm"><thead class="bg-muted"><tr><th v-for="column in shown" :key="column.key" class="p-3"><button class="font-medium" @click="sort(column.key)">{{ column.label }} {{ sortKey === column.key ? (descending ? '↓' : '↑') : '↕' }}</button></th></tr></thead><tbody><tr v-for="(row,index) in filtered" :key="index" class="border-t"><td v-for="column in shown" :key="column.key" class="p-3">{{ row[column.key] ?? '—' }}</td></tr><tr v-if="!filtered.length"><td :colspan="Math.max(shown.length,1)" class="p-6 text-center text-muted-foreground">No matching records</td></tr></tbody></table></div><p class="text-xs text-muted-foreground">Showing {{ filtered.length }} of {{ rows.length }} records</p></div></template>
